/* Little-endian fields, up to 32 bits. Callers provide enough storage and
 * zero the destination before packing: writes OR into the existing bytes.
 * Only 32-bit shifts, including fields that cross byte boundaries. */
static void wire_bits_put(uint8_t *b, uint32_t *pos, uint32_t v, uint32_t n)
{
    while (n--) {
        b[*pos >> 3] |= (uint8_t)((v & 1u) << (*pos & 7u));
        v >>= 1;
        ++*pos;
    }
}
static uint32_t wire_bits_get(const uint8_t *b, uint32_t *pos, uint32_t n)
{
    uint32_t v = 0;
    for (uint32_t i = 0; i < n; i++, ++*pos)
        v |= (uint32_t)((b[*pos >> 3] >> (*pos & 7u)) & 1u) << i;
    return v;
}
/* ------------------------------------------------------------ sizes --- */
/* Shared with engine-buffer placement: the queued recorder needs one runtime
 * counter per event, while the reference countdown implementation needs two. */
/* Host capacity fixtures can exercise the larger identifier space before a
 * new project schema and the device UI enable it in shipping builds. */
/* Patterns: 16 on each part (tracks 1..4), 8 on each MIDI-only track; arrays are NPAT wide. Records written before
 * 16 kept 8 a track (NPAT_V1: pattern_store.c reads them with that layout). */
_Static_assert(64 <= 128u && (4 + 4) * 16u <= 128u, "recorded-note identifiers (seven bits)");
