    p->raw[P5_SUSTAIN_FILTER] = p->raw[P5_SUSTAIN_AMP] = 127;
    p->raw[P5_RELEASE_FILTER] = p->raw[P5_RELEASE_AMP] = 35;
    p->raw[P5_RELEASE_ON] = 1;
    p->raw[P5_BEND] = 0;
    p->raw[P5_UNISON_COUNT] = 5;
