static void cz_sx_byte(uint8_t b)
{
    if(b>=0xf8)return;
    if(b==0xf0){if(PKV(45))return;PKV(43)=1;PKV(48)=0;PKV(44)=PKV(46)=0;}
    if(!PKV(43)||PKV(45))return;
    if((b&128)&&b!=0xf0&&b!=0xf7){PKV(43)=PKV(44)=PKV(46)=0;PKV(47)=1;return;}
    if(PKV(48)>=296u){PKV(43)=PKV(44)=PKV(46)=0;PKV(47)=1;return;}
    PKV(42)[PKV(48)++]=b;
    if(PKV(48)==2&&b!=0x44){PKV(43)=0;return;}
    if(PKV(48)==7 && PKV(42)[2]==0 && PKV(42)[3]==0 && (PKV(42)[4]&0xf0)==0x70){__asm__ volatile("" ::: "memory");PKV(44)=1;}
    if(PKV(48)==9&&(PKV(42)[5]==0x10||PKV(42)[5]==0x11)&&PKV(42)[7]==PKV(42)[4]&&b==0x31){__asm__ volatile("" ::: "memory");PKV(46)=1;}
    if(b==0xf7){PKV(43)=0;__asm__ volatile("" ::: "memory");PKV(45)=1;}
}
