        y = (drf_hp(&DRF_RS, (y * (((e0) + (((de) * (int32_t)(i)) >> 5)) >> 9)) >> 15, d->s) * 15200) >> 15;
        acc[i] += y;
        if (y > pk || -y > pk)
            pk = y < 0 ? -y : y;
