/* ---------------------------------------------------------- the hits --- */
/* the 808's instrument for a note (the other kits' drum role where its map has none) */
static uint32_t dr8_ins(uint32_t note, uint32_t role)
{
    uint32_t n = note >= 35u && note <= 81u ? note : 36u + (note + 120u - 36u) % 12u, k = DR_GM[n - 35u];
    return k == 0xFFu ? DR_OF_DVT[role % DVT_COUNT] : k;
}
/* lane d struck: instrument ins at velocity vel (its trigger level), TUNE for the voices tuned at the hit. Another
 * instrument than the one ringing starts from rest */
static void dr8_hit(dr8_t *d, uint32_t ins, uint32_t vel, const int16_t *p)
{
    int32_t tune = (p[P_E1] - 64) * 3 + d->pitch, lv;
    if (!d->nst)
        d->nst = 0x2F6E2B1 + (int32_t)(ins * 0x9E3779B9u);
    if (d->ins != ins)
        dr_off(d);
    lv = ((int32_t)(vel) * 132104);
    d->cache_valid=0;
    d->ins = (uint8_t)ins;
    d->t = 0;
    d->v = (int32_t)vel * 1742; /* 13.5 V at 127 */
    switch (ins) {
    case DR_SD:
        d->f = dr_tuned(dr_freq((uint32_t)((173.3) * 16)), tune);
        d->q = dr_damp(d->f, dr8_tau(d,((uint32_t)(18) * 441u / 10u))); /* Q 10 */
        d->f2 = dr_tuned(dr_freq((uint32_t)((336.0) * 16)), tune);
        d->q2 = dr_damp(d->f2, dr8_tau(d,((uint32_t)(9) * 441u / 10u))); /* Q 9.9 */
        dre_hit(&d->e[0], lv, dr8_tau(d,((uint32_t)(45) * 441u / 10u)));
        break;
    case DR_LT: case DR_MT: case DR_HT: case DR_LC: case DR_MC: case DR_HC: {
        uint32_t tau = dr8_tau(d,(((uint32_t)(DR_TOM[ins - DR_LT].ms) * 441u / 10u) * 10u / 46u));
        dre_hit(&d->e[0], lv, tau);
        dre_hit(&d->e[1], lv, tau * 7u / 10u);
        break;
    }
    case DR_RS:
        d->f = dr_tuned(dr_freq((uint32_t)((455) * 16)), tune);
        d->q = dr_damp(d->f, dr8_tau(d,((uint32_t)(12) * 441u / 10u)));
        d->f2 = dr_tuned(dr_freq((uint32_t)((1667) * 16)), tune);
        d->q2 = dr_damp(d->f2, dr8_tau(d,((uint32_t)(6) * 441u / 10u)));
        dre_hit(&d->e[0], lv, dr8_tau(d,(((uint32_t)(12) * 441u / 10u) * 10u / 46u)));
        break;
    case DR_CL:
        d->f = dr_tuned(dr_freq((uint32_t)((2500) * 16)), tune);
        d->q = dr_damp(d->f, dr8_tau(d,((uint32_t)(9) * 441u / 10u)));
        break;
    case DR_CP: {
        drf_t filter=dr8_filter(&DRF_CP,d->pitch);d->f=filter.a1;d->f2=filter.a2;d->q=filter.a3;
        d->s[2] = 0;
        d->s[3] = 0; /* the first burst now */
        dre_hit(&d->e[0], lv, dr8_tau(d,((uint32_t)(25) * 441u / 10u)));
        break;
    }
    case DR_MA:
        d->s[2] = 0;
        break;
    case DR_CB:
        dre_hit(&d->e[0], lv, dr8_tau(d,(((uint32_t)(50) * 441u / 10u) * 10u / 46u)));
        dre_hit(&d->e[1], lv, dr8_tau(d,(((uint32_t)(500) * 441u / 10u) * 10u / 46u)));
        break;
    case DR_CY:
        dre_hit(&d->e[0], lv, 64u); /* (dr_cy: DECY) */
        dre_hit(&d->e[1], lv, dr8_tau(d,((uint32_t)(40) * 441u / 10u)));
        break;
    case DR_OH:
        d->choke = 0;
        dre_hit(&d->e[0], lv, 64u); /* (dr_hat: DECY) */
        break;
    case DR_CH:
        dre_hit(&d->e[0], lv * 3 / 2, dr8_tau(d,(((uint32_t)(50) * 441u / 10u) * 10u / 46u))); /* (its level knob above the open hat's) */
        break;
    }
    d->on = 1;
}
/* the lane's block into y (n <= CTL): its circuit, the knobs of the part (p) as they are now, at DRUM's level */
static void dr8_run_into(dr8_t *d, const int16_t *p, int32_t *y, uint32_t n,dr_scratch_t *scratch)
{
    uint32_t i;
    for (i = 0; i < n; i++)
        y[i] = 0;
    if (!d->on)
        return;
    if ((((1u << DR_SD) | (1u << DR_LT) | (1u << DR_MT) | (1u << DR_HT) | (1u << DR_CP) | (1u << DR_MA)) >> d->ins) & 1u)
        for (i = 0; i < n; i++)
            scratch->nz[i] = (int32_t)(noise32(&d->nst) >> 17) - 16384;
    if (((((1u << DR_CY) | (1u << DR_OH) | (1u << DR_CH)) | (1u << DR_CB)) >> d->ins) & 1u) {
        dr_metal_tune(d,scratch);
        void (*volatile metal)(dr8_t *, uint32_t,dr_scratch_t *) = dr_metal;
        metal(d,n,scratch);
    }
    /* Both signatures cross the XIP/RAM distance through a register call. */
    switch (d->ins) {
    case DR_BD: do { void (*volatile run)(dr8_t *,const int16_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_bd; run(d,p,y,n,scratch); } while (0); break;
    case DR_SD: do { void (*volatile run)(dr8_t *,const int16_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_sd; run(d,p,y,n,scratch); } while (0); break;
    case DR_RS: do { void (*volatile run)(dr8_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_rs; run(d,y,n,scratch); } while (0); break;
    case DR_CL: do { void (*volatile run)(dr8_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_cl; run(d,y,n,scratch); } while (0); break;
    case DR_CP: do { void (*volatile run)(dr8_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_cp; run(d,y,n,scratch); } while (0); break;
    case DR_MA: do { void (*volatile run)(dr8_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_ma; run(d,y,n,scratch); } while (0); break;
    case DR_CB: do { void (*volatile run)(dr8_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_cb; run(d,y,n,scratch); } while (0); break;
    case DR_CY: do { void (*volatile run)(dr8_t *,const int16_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_cy; run(d,p,y,n,scratch); } while (0); break;
    case DR_OH: case DR_CH: do { void (*volatile run)(dr8_t *,const int16_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_hat; run(d,p,y,n,scratch); } while (0); break;
    default: do { void (*volatile run)(dr8_t *,const int16_t *,int32_t *,uint32_t,dr_scratch_t *) = dr_tom; run(d,p,y,n,scratch); } while (0); break;
    }
    for (i = 0; i < n; i++)
        y[i] = (y[i] * 6800) >> 12;
    if (d->t > ((uint32_t)(6000) * 441u / 10u))
        dr_off(d);
}
static void dr8_run(dr8_t *d,const int16_t *p,int32_t *y,uint32_t n)
{ dr8_run_into(d,p,y,n,&PKV(49)); }
