/* ---- exp(x) to about an ulp for |x| < 0.35 (envelope and detector rates) ---- */
static inline float d9_exp_small(float x)
{
    if (x < -0.35f || x > 0.35f)
        return fm_expf(x);
    float p = 1.0f + x * (1.0f / 8.0f);
    p = 1.0f + x * (1.0f / 7.0f) * p;
    p = 1.0f + x * (1.0f / 6.0f) * p;
    p = 1.0f + x * (1.0f / 5.0f) * p;
    p = 1.0f + x * (1.0f / 4.0f) * p;
    p = 1.0f + x * (1.0f / 3.0f) * p;
    p = 1.0f + x * 0.5f * p;
    return 1.0f + x * p;
}
/* ceil for 0 <= x < 2^31 */
static inline int32_t d9_ceil(float x)
{
    int32_t i = (int32_t)x;
    return (float)i < x ? i + 1 : i;
}
/* ===================================================================== */
/* Envelope: Web Audio AudioParam with setValueAtTime and                 */
/* exponentialRampToValueAtTime (the only two automation calls 9W9 makes) */
/* ===================================================================== */
typedef struct {
    float v; /* value the next tick returns           */
    float cur; /* value the last tick returned (9W9's p->value; a new
                       ramp starts from it)                  */
    float r; /* per-sample ratio while ramping        */
    float v0, v1; /* ramp start / end                      */
    float l2r; /* log2(v1 / v0)                         */
    float t1; /* ramp length in samples (9W9's t1)     */
    int32_t k; /* ramp length in ticks before v1        */
    int32_t left; /* ticks of ramp left (0 = constant)     */
} d9_env_t;
static inline void d9_env_set(d9_env_t *e, float v)
{
    e->v = v;
    e->cur = v;
    e->v1 = v;
    e->left = 0;
}
/* exponentialRampToValueAtTime(v1, now + t1 samples). Tick k (k = 0 the first
 * tick after this call) returns v0 * (v1/v0)^(k/t1) while k + 1 < t1, then v1.
 * Out of line: it runs a few times per note, never per sample. */
static void d9_env_exp(d9_env_t *e, float v1, float t1)
{
    float v0 = e->cur < 1.0e-9f ? 1.0e-9f : e->cur;
    if (v1 < 1.0e-9f)
        v1 = 1.0e-9f;
    if (!(t1 > 0.0f))
        t1 = 1.0f;
    e->v0 = v0;
    e->v1 = v1;
    e->t1 = t1;
    e->k = d9_ceil(t1) - 1;
    e->left = e->k;
    if (e->k <= 0) {
        e->left = 0;
        e->v = v1;
        e->cur = v0;
        return;
    }
    e->l2r = fm_log2f(v1 / v0);
    e->r = d9_exp_small(e->l2r * 0.693147180559945f / t1);
    e->v = v0;
    e->cur = v0;
}
static inline float d9_env_tick(d9_env_t *e)
{
    const float o = e->v;
    e->cur = o;
    if (e->left) {
        if (--e->left)
            e->v *= e->r;
        else
            e->v = e->v1;
    }
    return o;
}
/* back onto the closed form; once per block */
static inline void d9_env_anchor(d9_env_t *e)
{
    if (e->left)
        e->v = e->v0 * fm_exp2f(e->l2r * ((float)(e->k - e->left) / e->t1));
}
/* ===================================================================== */
/* Biquad (Web Audio / RBJ), direct form 1 as 9W9                         */
/* ===================================================================== */
enum { D9_LP = 0, D9_HP, D9_BP };
typedef struct {
    float b0, b1, b2, a1, a2;
    float x1, x2, y1, y2;
} d9_biquad_t;
static inline void d9_biquad_set(d9_biquad_t *f, int type, float freq, float q)
{
    float fc = freq / (44100.0f * 0.5f);
    if (fc >= 1.0f) fc = 0.9999f;
    if (fc <= 0.0f) fc = 0.0001f;
    const float w0 = 3.14159265358979f * fc;
    const float sh = fm_sinf(0.5f * w0);
    const float cosw0 = 1.0f - 2.0f * sh * sh;
    const float sinw0 = fm_sinf(w0);
    if (q < 0.0001f) q = 0.0001f;
    const float alpha = sinw0 / (2.0f * q);
    float b0, b1, b2;
    const float a0 = 1.0f + alpha, a1 = -2.0f * cosw0, a2 = 1.0f - alpha;
    if (type == D9_LP) {
        b0 = (1.0f - cosw0) * 0.5f; b1 = 1.0f - cosw0; b2 = (1.0f - cosw0) * 0.5f;
    } else if (type == D9_HP) {
        b0 = (1.0f + cosw0) * 0.5f; b1 = -(1.0f + cosw0); b2 = (1.0f + cosw0) * 0.5f;
    } else {
        b0 = alpha; b1 = 0.0f; b2 = -alpha;
    }
    const float inv = 1.0f / a0;
    f->b0 = b0 * inv; f->b1 = b1 * inv; f->b2 = b2 * inv;
    f->a1 = a1 * inv; f->a2 = a2 * inv;
}
static inline void d9_biquad_reset(d9_biquad_t *f) { f->x1 = f->x2 = f->y1 = f->y2 = 0.0f; }
static inline float d9_biquad_tick(d9_biquad_t *f, float in)
{
    const float y = f->b0 * in + f->b1 * f->x1 + f->b2 * f->x2 - f->a1 * f->y1 - f->a2 * f->y2;
    f->x2 = f->x1; f->x1 = in;
    f->y2 = f->y1; f->y1 = y;
    return y;
}
/* ===================================================================== */
/* Oscillator: Web Audio triangle on a uint32 phase                       */
/* ===================================================================== */
static inline uint32_t d9_inc(float hz) { return (uint32_t)(hz * 97391.548752834467f); }
/* 4p - 1 rising over the first half, 3 - 4p falling over the second */
static inline float d9_tri(uint32_t ph)
{
    const uint32_t u = ph ^ (uint32_t)((int32_t)ph >> 31);
    return (float)(int32_t)u * (1.0f / 1073741824.0f) - 1.0f;
}
/* ===================================================================== */
/* tanh from the table                                                    */
/* ===================================================================== */
static inline float d9_tanh(float u)
{
    const float a = fm_fabsf(u) * 128.0f;
    float t;
    if (a >= (float)1024) {
        t = 1.0f;
    } else {
        const int32_t i = (int32_t)a;
        const float fr = a - (float)i;
        t = P5_TANH[i] + (P5_TANH[i + 1] - P5_TANH[i]) * fr;
    }
    return u < 0.0f ? -t : t;
}
/* ===================================================================== */
/* The voice / master distortion stage (er99_shape_st), 7 types           */
/* ===================================================================== */
typedef struct {
    int32_t type;
    float k; /* drive, floored at 0.01            */
    float g; /* diode: 1/tanh(k); others: 1/k when k < 1 else 1 */
    float c1, c2; /* type-specific constants (see prep) */
} d9_shape_t;
static inline void d9_shape_prep(d9_shape_t *s, float drive, int type)
{
    const float k = drive > 0.01f ? drive : 0.01f;
    s->type = type;
    s->k = k;
    s->g = k < 1.0f ? 1.0f / k : 1.0f;
    s->c1 = s->c2 = 0.0f;
    switch (type) {
    case 0: s->g = 1.0f / d9_tanh(k); break;
    case 2: s->c1 = 0.08f * k; s->c2 = k < 1.0f ? k : 1.0f; break; /* SAT: m */
    case 3: { /* BFZ: m */
        float m = (k - 0.85f) / 1.15f;
        s->c1 = m < 0.0f ? 0.0f : (m > 1.0f ? 1.0f : m);
        s->c2 = k * 2.5f;
        break;
    }
    case 6: /* crush */
        s->c1 = 1.5f + 9.0f / k;
        s->c2 = k < 1.0f ? 1.0f : 1.0f + (k - 1.0f) * 1.7f;
        s->g = 1.0f / s->c1;
        break;
    default: break;
    }
}
/* types 1..6, out of line (the switch is big; the default type is inline below) */
static float d9_shape_other(const d9_shape_t *s, float x, float *st)
{
    const float k = s->k;
    switch (s->type) {
    case 1: { /* asymmetric soft clip */
        const float v = (d9_tanh(x * k + 0.35f) - 0.33638f) * 0.958f;
        return v * s->g;
    }
    case 5: { /* wavefolder */
        float v = x * k;
        for (int i = 0; i < 3; ++i) {
            if (v > 1.0f) v = 2.0f - v;
            if (v < -1.0f) v = -2.0f - v;
        }
        float body = x * k;
        if (body > 1.0f) body = 1.0f;
        if (body < -1.0f) body = -1.0f;
        v = 0.62f * v + 0.38f * body;
        return v * s->g;
    }
    case 6: { /* bitcrush: quantise + decimate */
        float q = fm_floorf(x * s->c1 + 0.5f) * s->g;
        st[1] += 1.0f;
        if (st[1] >= s->c2) { st[1] -= s->c2; st[0] = q; }
        return st[0];
    }
    case 2: { /* SAT */
        const float u = x * k + s->c1 * x * x;
        const float wet = u / (1.0f + fm_fabsf(u));
        const float m = s->c2;
        const float v = (1.0f - 0.65f * m) * x * m + 0.65f * m * wet * 1.35f;
        return v * s->g;
    }
    case 3: { /* BFZ */
        const float u = x * s->c2 + 0.22f;
        const float wet = (u / (1.0f + fm_fabsf(u)) - 0.18033f) * 1.05f;
        const float m = s->c1;
        return (1.0f - m) * x + m * wet;
    }
    case 4: { /* PDIST */
        float u = x * k + 0.12f;
        if (u > 1.0f) u = 1.0f;
        if (u < -1.0f) u = -1.0f;
        const float y0 = 0.12f - (0.12f * 0.12f * 0.12f) / 3.0f;
        return ((u - u * u * u * (1.0f / 3.0f)) - y0) * (1.5f / 1.479f);
    }
    default: /* 0: the 909's diode pair */
        return d9_tanh(k * x) * s->g;
    }
}
static inline float d9_shape(const d9_shape_t *s, float x, float *st)
{
    if (s->type == 0) /* Diode: every voice's default */
        return d9_tanh(s->k * x) * s->g;
    return d9_shape_other(s, x, st);
}
/* ===================================================================== */
/* White noise: xorshift32, uniform [-1, 1) (9W9's wa_noise)              */
/* ===================================================================== */
static inline float d9_noise(uint32_t *s)
{
    uint32_t x = *s;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *s = x;
    return (float)x * (1.0f / 2147483648.0f) - 1.0f;
}
enum { D9_BD, D9_SD, D9_LT, D9_MT, D9_HT, D9_RS, D9_CP, D9_CH, D9_OH, D9_CR, D9_RD, D9_NUM, D9_KIT = D9_NUM };
/* BD and SD: 9W9's er99_bt_t */
typedef struct {
    /* panel values (engineering units) */
    float tune, sweep_depth, sweep_time, decay, attack, click_tone, level;
    float tune2, osc2_mix, snappy, noise_decay, noise_hp, amp_hold, pitch_mod;
    float drive;
    int32_t dist_type;
    d9_shape_t shape;
    /* runtime */
    uint32_t ph, ph2;
    d9_env_t pitch, amp, click_env, noise_env;
    d9_biquad_t click_lp, noise_hpf, noise_lpf, dc_block;
    int32_t noise_hold, noise_gated, amp_hold_left, bd_phold, impulse, mute;
    int32_t click_stale, click_warm; /* skipped click filter: see d9_render_bd */
    float bd_df, bd_mult, bd_base, out_gain;
    float crush_st[2];
} d9_bt_t;
/* LT/MT/HT: 9W9's er99_tom_t (three VCOs); reads the panel from a d9_bt_t */
typedef struct {
    uint32_t ph[3];
    d9_env_t env[3], pitch, noise_env;
    d9_biquad_t noise_bp, dc_block;
    float out_gain, noise_level;
    float crush_st[2];
    int32_t mute;
    int32_t stick_stale, stick_warm; /* skipped stick filter: see d9_render_tom */
} d9_tom_t;
typedef struct {
    float tune, tune2, res, decay, noise_mix, drive, level, accent;
    int32_t dist_type;
    d9_shape_t shape;
    d9_biquad_t bp1, bp2, hp;
    d9_env_t amp;
    float crush_st[2];
    int32_t impulse, mute;
} d9_rim_t;
typedef struct {
    float tune, res, spread, burst_decay, tail_decay, tail_level, drive, level, accent;
    int32_t dist_type;
    d9_shape_t shape;
    d9_biquad_t bp, hp;
    d9_env_t burst, tail;
    float crush_st[2];
    float next_pulse;
    int32_t pulse_index, mute;
} d9_clap_t;
typedef struct {
    float decay, volume, pitch, drive;
    int32_t dist_type;
    d9_shape_t shape;
    /* Melodee: synthesized metal, no recorded cymbal buffers. */
    uint32_t ph[6], noise;
    d9_biquad_t bp, hp;
    int32_t playing, kind;
    d9_env_t out;
    float crush_st[2];
    int32_t mute;
} d9_smp_t;
struct drum909 {
    d9_bt_t bt[5]; /* BD SD LT MT HT panels; BD and SD voices */
    d9_tom_t tom[3]; /* LT MT HT voices */
    d9_rim_t rim;
    d9_clap_t clap;
    d9_smp_t smp[4]; /* CH OH CR RD */
    float pan_l[D9_NUM], pan_r[D9_NUM]; /* X0X: each voice's pan (x0x_pan_gains) */
    float pan_lc[D9_NUM], pan_rc[D9_NUM]; /* where each voice's pan gains are now, gliding to pan_l/r */
    float pan_dl[D9_NUM], pan_dr[D9_NUM]; /* this block's glide per sample */
    float accent, vel_depth; /* kit */
    uint32_t noise;
    float nz_buf[(256 + 2 * 32)]; /* noise, linear; the block plus >= D9_NZ_HIST before it */
    int32_t nz_pos; /* where the next block's noise starts */
    uint8_t pots[D9_NUM + 1][9];
};
typedef struct drum909 drum909_t;
void drum909_init(drum909_t *d);
void drum909_trigger(drum909_t *d, int voice, float vel);
void drum909_render(drum909_t *d, float *dry, int n);
/* X0X stereo: each voice placed by its PAN into dry_l / dry_r; all centred, both are
 * drum909_render's dry exactly */
void drum909_render_st(drum909_t *d, float *dry_l, float *dry_r, int n);
void drum909_pan_settle(drum909_t *d); /* every pan to its target at once (the kit is silent: no zipper) */
int drum909_nparams(int voice);
const x0x_param_t *drum909_param(int voice, int i);
void drum909_set(drum909_t *d, int voice, int i, int value);
int drum909_get(const drum909_t *d, int voice, int i);
/* true while any voice is still sounding (for a caller that wants to skip work) */
int drum909_active(const drum909_t *d);
/* Melodee keeps the circuit voices; metallic voices are synthesized below. */
/* 9W9's back-to-back diode rounding at the two fixed drives the circuits use */
static inline float d9_diode16(float x) { return d9_tanh(1.6f * x) * 1.0849887132644653f; }
static inline float d9_diode20(float x) { return d9_tanh(2.0f * x) * 1.037314772605896f; }
