    g = gt[fcr >> 4] + (((gt[(fcr >> 4) + 1] - gt[fcr >> 4]) * (fcr & 15)) >> 4);
    kd = SID_RES_K[SID_6581][clamp(p[P_E7], 0, 127) >> 3];
