            if(noisy){
                if((((ph^0x08000000u)&0x0fffffffu)+inc)>>28){noise=sid_noise_advance(noise,ph,inc);nb=sid_noise_bits(noise);}
                w=nb;
            }else w=wb?sid_wave_out(wb,0,q,q,pt):0u;
            ph=q;
