/* the lane's drum, one block into y; 0 once it has rung out */
static int cr_run(dlk_ch_t *__restrict c, int32_t *y, uint32_t n)
{
    const cr_sound_t *s = &CR_SOUNDS[c->rec];
    uint32_t i, t0 = c->t;
    int live = t0 < 200u;
    if (s->hz[0]) { /* the networks: struck by the pulse, ringing on */
        int32_t d0, f0 = c->f[0], pk = 0;
        dre_next(&c->e[1], &d0);
        if (s->drop)
            f0 += (int32_t)(((int64_t)f0 * (((d0 >> 9) * s->drop) / 100)) >> 15);
        for (i = 0; i < n; i++) {
            int32_t x = t0 + i < 200u ? cr_pulse(c, t0 + i) * 16 : 0, r;
            r = (int32_t)(((int64_t)dr_res(&c->lp[0], &c->bp[0], f0, c->q[0], x) * c->k[0]) >> 16);
            if (s->hz[1])
                r += (int32_t)(((int64_t)dr_res(&c->lp[1], &c->bp[1], c->f[1], c->q[1], x) * c->k[1]) >> 16);
            r = clamp(r, -65535, 65535);
            y[i] += r;
            pk = r > pk ? r : -r > pk ? -r : pk;
        }
        live |= pk >= 8;
    }
    if (s->nf)
        live |= dlk_noise(c, y, n, s->nf, 0);
    if (s->sq[0]) { /* the squares */
        int32_t e0, de = dre_next(&c->e[2], &e0);
        for (i = 0; i < n; i++) {
            int32_t x = (c->ph[0] < 2060725309u ? 8192 : -8192) + (c->ph[1] < 2060725309u ? 8192 : -8192);
            c->ph[0] += c->inc[0];
            c->ph[1] += c->inc[1];
            y[i] += (((drf_bp(&c->sf, x, c->ss) * (((e0) + (((de) * (int32_t)(i)) >> 5)) >> 9)) >> 15) * s->sg) >> 12;
        }
        live |= c->e[2].e >= (1 << 11);
    }
    if (c->tk < 16384) /* TONE */
        for (i = 0; i < n; i++)
            y[i] = c->ts += (int32_t)(((int64_t)(y[i] - c->ts) * c->tk) >> 14);
    return live && t0 < ((uint32_t)(6000) * 441u / 10u);
}
