            do { if (add) for (i = 0; i < n; i++) { g += dg; out[i] += ((ph&0x800000u)?-1.0f/2048.0f:0.0f); ph += fq; } else for (i = 0; i < n; i++) { g += dg; out[i] = ((ph&0x800000u)?-1.0f/2048.0f:0.0f); ph += fq; } } while (0);
