    float g = s->g[k], dg = s->dg[k];
    if (eng == FM6_MODERN) {
        if (in)
            do { if (add) for (i = 0; i < n; i++) { g += dg; out[i] += ((fm6_sin((int32_t)fm6_phase(ph, in[i])) * g)); ph += fq; } else for (i = 0; i < n; i++) { g += dg; out[i] = ((fm6_sin((int32_t)fm6_phase(ph, in[i])) * g)); ph += fq; } } while (0);
        else
            do { if (add) for (i = 0; i < n; i++) { g += dg; out[i] += ((fm6_sin((int32_t)(ph & 0xFFFFFFu)) * g)); ph += fq; } else for (i = 0; i < n; i++) { g += dg; out[i] = ((fm6_sin((int32_t)(ph & 0xFFFFFFu)) * g)); ph += fq; } } while (0);
    } else if (eng == FM6_MARK1) {
        if (in)
            do { if (add) for (i = 0; i < n; i++) { g += dg; out[i] += ((1.0f / 16777216.0f) * fm6_mki((int32_t)fm6_phase(ph, in[i]), (int32_t)g)); ph += fq; } else for (i = 0; i < n; i++) { g += dg; out[i] = ((1.0f / 16777216.0f) * fm6_mki((int32_t)fm6_phase(ph, in[i]), (int32_t)g)); ph += fq; } } while (0);
        else
            do { if (add) for (i = 0; i < n; i++) { g += dg; out[i] += ((1.0f / 16777216.0f) * fm6_mki((int32_t)(ph & 0xFFFFFFu), (int32_t)g)); ph += fq; } else for (i = 0; i < n; i++) { g += dg; out[i] = ((1.0f / 16777216.0f) * fm6_mki((int32_t)(ph & 0xFFFFFFu), (int32_t)g)); ph += fq; } } while (0);
    } else {
        if (in)
            do { if (add) for (i = 0; i < n; i++) { g += dg; out[i] += ((1.0f / 16777216.0f) * fm6_opl((int32_t)fm6_phase(ph, in[i]), (int32_t)g)); ph += fq; } else for (i = 0; i < n; i++) { g += dg; out[i] = ((1.0f / 16777216.0f) * fm6_opl((int32_t)fm6_phase(ph, in[i]), (int32_t)g)); ph += fq; } } while (0);
        else
            do { if (add) for (i = 0; i < n; i++) { g += dg; out[i] += ((1.0f / 16777216.0f) * fm6_opl((int32_t)(ph & 0xFFFFFFu), (int32_t)g)); ph += fq; } else for (i = 0; i < n; i++) { g += dg; out[i] = ((1.0f / 16777216.0f) * fm6_opl((int32_t)(ph & 0xFFFFFFu), (int32_t)g)); ph += fq; } } while (0);
    }
