static void fm6_sx_byte(uint8_t b)
{
    if (b == 0xF0) {
        PKV(71) = !PKV(70) && !PKV(68);
        if (PKV(71))
            PKV(69) = 0; /* a pending frame belongs to the main loop, the scratch to a job */
    }
    if (!PKV(71) || b >= 0xF8u)
        return; /* (realtime may occur anywhere in SysEx) */
    if ((b & 0x80u) && b != 0xF0u && b != 0xF7u) {
        PKV(71) = 0; /* a channel/system status cancels the frame */
        return;
    }
    if (PKV(68) || PKV(69) >= 4104u || (PKV(69) == 1u && b != 0x43)) {
        PKV(71) = 0; /* a job took the scratch, too long, or not Yamaha */
        return;
    }
    if (PKV(69) == 1u) { /* Yamaha's: the scratch holds this frame now */
        PKV(67)++;
        PKV(66).raw[0] = 0xF0;
    }
    if (PKV(69))
        PKV(66).raw[PKV(69)] = b;
    PKV(69)++;
    if (b == 0xF7) {
        PKV(71) = 0;
        __asm__ volatile("" ::: "memory");
        PKV(70) = 1;
    }
}
