static const param_desc_t *global_desc(uint32_t id)
{
    if(id>=G_MFXTONE && id<=G_MFX3TONE){uint32_t type=PKV(14).g[G_MFXTYPE+(id-G_MFXTONE)*4u];if(fx_sloop_swept(type))return fx_pedal_desc(type,4,&GP[id]);}
    if(param_master_fx(id) && (id-G_MFXTYPE)%4u>=2u){
        /* (statics: hoisted) */static const char *const character[]={"CHAR","DEPTH","DEPTH","FOCUS","JITTER","BITE","REPEAT","DECAY","DAMP","DEPTH","","","TONE","TONE","TONE","TONE","ALIAS","DEPTH","DEPTH","DEPTH"};
        uint32_t base=G_MFXTYPE+(id-G_MFXTYPE)/4u*4u,type=(uint32_t)clamp(PKV(14).g[base],0,(sizeof(N_AUDIO_FX) / sizeof((N_AUDIO_FX)[0]))-1);PKV(112)=GP[id];
        if(fx_sloop_type(type))return fx_pedal_desc(type,id-base,&GP[id]);
        if(id-base==3u)PKV(112).label=character[type];else if(type>=6u && type<=8u){PKV(112).label=type==6u?"TIME":"SIZE";PKV(112).fmt=F_PCT;}
        return &PKV(112);
    }
    return &GP[id];
}
