static int32_t lfo_wave(track_t *t, uint32_t ph)
{
    switch (t->p[P_LWAVE]) {
    case 1:
        return osc_tri(ph);
    case 2:
        return (int32_t)(ph >> 16) - 32768;
    case 3:
        return ph < 0x80000000u ? 32767 : -32767;
    case 4:
        return (int32_t)(t->lfo_rnd >> 16) - 32768;
    default:
        return osc_sine(ph);
    }
}
/* the S&H value of a new LFO cycle. Parts 1..3 draw it from the shared generator (rng); part 4 has its
 * own xorshift, so the shared sequence, which also seeds the engines' noise (PHYS, VOICE, ..), does not
 * depend on part 4's LFO (the golden renders rely on it) */
static uint32_t lfo_rand(track_t *t)
{
    uint32_t s = t->lfo_rnd ? t->lfo_rnd : 0x9E3779B9u;
    if ((uint32_t)(t - PKV(11)) < 3u)
        return rng();
    s ^= s << 13;
    s ^= s >> 17;
    s ^= s << 5;
    return s;
}
/* LFO 2 (1.2, #154; params.c N_LSYNC): with SYNC on, one cycle lasts the note value in the sequencer's units (mix.c),
 * whatever RATE says (the matrix's RATE too), so it cannot slide against the song: the phase advances
 * units x 2^32 / cycle a block, the remainder carried. Cycles are x times 1024 units, so units x 2^22 / x; a burst goes
 * in 512 units at a time to stay in 32 bits. OFF: RATE's table, as before */
static uint32_t seq_div_samples(uint32_t div); /* (mix.c) */
