/* DC blocker (~2 Hz), always on: a leaky integrator of the input (Q6 state) subtracted from it.
 * The >> 12 step keeps its remainder (error feedback, 0..4095) and adds it to the next one, so no
 * part of the step is lost: the state follows the input exactly, down to 0 after the sound stops.
 * (A rounded step of (x - dc) / 4096 would stop moving at |x - dc| < 2048 and leave an offset of up
 * to +-31 at the output after silence.) */
static inline int32_t dc_block(int32_t x, int32_t *dc, int32_t *err)
{
    int32_t e = x * 64 - *dc + *err, d = e >> 12;
    *err = e - d * 4096;
    *dc += d;
    return x - ((*dc + 32) >> 6);
}
static void master_out(int32_t *l, int32_t *r)
{
    int32_t al, ar, a;
    *l = dc_block(*l, &PKV(179), &PKV(181));
    *r = dc_block(*r, &PKV(180), &PKV(182));
    al = *l < 0 ? -*l : *l;
    ar = *r < 0 ? -*r : *r;
    a = al > ar ? al : ar;
    if (a > PKV(178))
        PKV(178) += (a - PKV(178)) >> 2;
    else if (PKV(178) > 26000)
        PKV(178) -= ((PKV(178) - 26000) >> 12) + 1;
    if (PKV(178) > 26000) {
        int32_t g = (int32_t)(((uint32_t)26000 << 15) / (uint32_t)PKV(178)); /* < 32768 */
        *l = ((*l >> 4) * g) >> 11; /* >> 4 first: |l| may be far above Q15 */
        *r = ((*r >> 4) * g) >> 11;
    }
    *l = softclip(*l);
    *r = softclip(*r);
}
