/* USB full-speed device on USB0: a
 * class-compliant USB-MIDI interface. All SIE traffic happens in one place,
 * usb_poll(), called from the TIMER5 ISR at 2 kHz, so INDEX is never shared
 * and no USB IRQ is needed. MIDI in goes to a ring the audio ISR drains;
 * MIDI out (the panel keys) comes from a ring the audio ISR fills.
 * SysEx F0 22 24 35 7D F7 (the stock soft key, tools/fm1_softkey.py) asks
 * the main loop to enter UBOOT. VID 0x1209 / PID 0x0001 is the pid.codes
 * TEST id: fine for the bench, must be replaced before any release.
 * MELODEE_CDC=1 adds a CDC-ACM serial function (IAD composite: EP2 notify,
 * EP3 bulk data) for the console in console.c.
 * MELODEE_USB_AUDIO=1 instead adds one duplex UAC1 function (usb_audio.c),
 * "Melodee": stereo playback (EP2 OUT, explicit feedback on EP3) and
 * stereo master or four-track recording (EP2 IN), 16 or 24 bit at 44.1 kHz.
 * Their endpoints are served from the TIMER5 ISR by elapsed time (ua_service,
 * main.c), nested in the render too; usb_poll never runs nested, so the two
 * never interleave. Either can be left out of the configuration (ua_off, the
 * menu's USB AUDIO); usb_replug makes the host see the change. MELODEE_USB_HOST=1 adds usb_host.c: the menu's
 * USB HOST makes the port the host of a USB-MIDI controller (usb.up is 0 meanwhile). The update
 * loader leaves both off: MIDI only. */
/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 USB0 full-speed device controller, register level only
 * The protocol (descriptors, EP0 requests,
 * MIDI / CDC / SysEx) is the driver src/usb.c, shared with the update loader
 * and the host tests; this header is every USB register access it makes.
 *
 *   fm1_usb_reset()        CON0 = CON1 = 0, pads detached; wait >= 20 ms
 *   fm1_usb_attach(ep0)    clock, EP DMA defaults, PHY on, D+ pull-up
 *   fm1_usb_off()          detach: controller off, pads inputs
 *   SIE (MUSB byte map):   fm1_usb_sie_on, _wr_start / _rd_start, _done, _data
 *   EP DMA:                fm1_usb_ep0_buf, fm1_usb_ep_txbuf / _rxbuf,
 *                          fm1_usb_ep0_send / fm1_usb_ep_send (csync first),
 *                          fm1_usb_rx_sync (ssync before reading an RX buffer)
 *   EP4 (own slots): fm1_usb_ep4_txbuf, fm1_usb_ep4_send (csync first);
 *                          isochronous mode is TXCSR2 bit 6 through the SIE (usb.c)
 *   fm1_usb_ep_enable(m)   CON0 &= ~(m << 19), m = bit per endpoint
 *   fm1_usb_sof_take()     SOF pending -> clear, 1
 *   fm1_usb_host_attach(ep0) / fm1_usb_line()   host mode (usb_host.c): pull-downs, PHY, VBUS valid; D+/D- levels
 * No IRQ: everything is polled (usb_poll from the TIMER5 ISR). */
       
/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM1_INLINE: register helpers that must inline into their caller, so the
 * SFR access sequence (and its timing, in ISRs and IRQ-off sections) is the
 * one written at the call site; -Os would otherwise out-line a helper with
 * several callers. RAM-resident code (.ram_text) may only use these, never
 * a called helper (build.py checks .ram_text for calls). */
       
static inline void fm1_usb_reset(void)
{
    (*(volatile uint32_t *)0x11800u) = 0;
    (*(volatile uint32_t *)0x11804u) = 0;
    (*(volatile uint32_t *)0x51000u) = 0x0Cu;
}
static inline void fm1_usb_attach(void *ep0)
{
    uint32_t n;
    (*(volatile uint32_t *)0x10010u) &= ~3u; /* USB clock = PLL48M */
    (*(volatile uint32_t *)0x11818u) = (uint32_t)(uintptr_t)ep0;
    for (n = 1; n <= 3u; n++)
        (*(volatile uint32_t *)(0x11820u + 8u * ((n) - 1u))) = (uint32_t)(uintptr_t)ep0;
    (*(volatile uint32_t *)0x1183Cu) = (uint32_t)(uintptr_t)ep0;
    (*(volatile uint32_t *)0x51000u) |= (1u << 10) | (1u << 9);
    (*(volatile uint32_t *)0x51000u) &= ~(1u << 11);
    (*(volatile uint32_t *)0x51000u) |= 1u << 12;
    (*(volatile uint32_t *)0x11800u) &= ~0x4035u;
    (*(volatile uint32_t *)0x11804u) = 0;
    (*(volatile uint32_t *)0x11800u) |= 1u;
    (*(volatile uint32_t *)0x51000u) &= ~0xF0u;
    (*(volatile uint32_t *)0x51000u) |= 0x40u; /* D+ pull-up: attach */
    (*(volatile uint32_t *)0x11800u) |= 0x3Cu;
}
static inline void fm1_usb_off(void)
{
    (*(volatile uint32_t *)0x11800u) = 0;
    (*(volatile uint32_t *)0x51000u) = 0x0Cu;
}
/* Host (A-device) on USB0, the sequence of the AC79 SDK's usb_h_sie_init(0): D+ / D- digital inputs with their
 * pull-downs (USB_IO_CON0 DPDIE DMDIE DPPD DMPD, no pull-ups), PHY on, SIE out of reset, VBUS valid, CID 0
 * (A-device). The caller waits >= 20 ms after fm1_usb_reset and again after this before touching the SIE, then
 * writes DEVCTL = 3 (session + host request). Nothing here drives VBUS: the port needs power from outside. */
static inline void fm1_usb_host_attach(void *ep0)
{
    uint32_t n;
    (*(volatile uint32_t *)0x10010u) &= ~3u; /* USB clock = PLL48M */
    (*(volatile uint32_t *)0x11818u) = (uint32_t)(uintptr_t)ep0;
    for (n = 1; n <= 3u; n++)
        (*(volatile uint32_t *)(0x11820u + 8u * ((n) - 1u))) = (uint32_t)(uintptr_t)ep0;
    (*(volatile uint32_t *)0x1183Cu) = (uint32_t)(uintptr_t)ep0;
    (*(volatile uint32_t *)0x11800u) = 0;
    (*(volatile uint32_t *)0x11804u) = 0;
    (*(volatile uint32_t *)0x51000u) = 0;
    (*(volatile uint32_t *)0x51000u) |= (1u << 10) | (1u << 9) | (1u << 5) | (1u << 4);
    (*(volatile uint32_t *)0x51000u) &= ~((1u << 11) | (1u << 8));
    (*(volatile uint32_t *)0x11800u) |= 0x25u; /* PHY_ON | USB_NRST | VBUS */
}
/* D+ / D- single-ended levels (CON0 bit 17 / 16): both 0 = nothing attached, else a device pulls one up */
static inline uint32_t fm1_usb_line(void) { return ((*(volatile uint32_t *)0x11800u) >> 16) & 3u; }
/* SIE access through CON1: only while CON0.bit2 (USB_NRST) is set */
static inline uint32_t fm1_usb_sie_on(void) { return (*(volatile uint32_t *)0x11800u) & 4u; }
static inline void fm1_usb_sie_wr_start(uint32_t r, uint32_t v)
{
    (*(volatile uint32_t *)0x11804u) = ((r << 8) & 0xFFFF00u) | (v & 0xFFu);
    __asm__ volatile("csync" ::: "memory");
}
static inline void fm1_usb_sie_rd_start(uint32_t r)
{
    (*(volatile uint32_t *)0x11804u) = ((r << 8) & 0xFFBF00u) | 0x4000u;
    __asm__ volatile("csync" ::: "memory");
}
static inline uint32_t fm1_usb_sie_done(void) { return (*(volatile uint32_t *)0x11804u) & 0x8000u; }
static inline uint32_t fm1_usb_sie_data(void) { return (*(volatile uint32_t *)0x11804u) & 0xFFu; }
static inline void fm1_usb_ep0_buf(void *p) { (*(volatile uint32_t *)0x11818u) = (uint32_t)(uintptr_t)p; }
static inline void fm1_usb_ep_txbuf(uint32_t ep, void *p) { (*(volatile uint32_t *)(0x1181Cu + 8u * ((ep) - 1u))) = (uint32_t)(uintptr_t)p; }
static inline void fm1_usb_ep_rxbuf(uint32_t ep, void *p) { (*(volatile uint32_t *)(0x11820u + 8u * ((ep) - 1u))) = (uint32_t)(uintptr_t)p; }
static inline void fm1_usb_ep0_send(void *p, uint32_t n)
{
    __asm__ volatile("csync" ::: "memory"); /* the buffer is written before the DMA starts */
    (*(volatile uint32_t *)0x11818u) = (uint32_t)(uintptr_t)p;
    (*(volatile uint32_t *)(0x11808u + 4u * (0))) = n;
}
static inline void fm1_usb_ep_send(uint32_t ep, void *p, uint32_t n)
{
    __asm__ volatile("csync" ::: "memory");
    (*(volatile uint32_t *)(0x1181Cu + 8u * ((ep) - 1u))) = (uint32_t)(uintptr_t)p;
    (*(volatile uint32_t *)(0x11808u + 4u * (ep))) = n;
}
/* EP4 IN (the USB audio stream, isochronous): its DMA address and count have their own
 * registers (SDK usb_set_dma_taddr / usb_write_ep_cnt, id 0, ep 4) */
static inline void fm1_usb_ep4_txbuf(void *p) { (*(volatile uint32_t *)0x11838u) = (uint32_t)(uintptr_t)p; }
static inline void fm1_usb_ep4_send(void *p, uint32_t n)
{
    __asm__ volatile("csync" ::: "memory");
    (*(volatile uint32_t *)0x11838u) = (uint32_t)(uintptr_t)p;
    (*(volatile uint32_t *)0x11834u) = n;
    __asm__ volatile("csync" ::: "memory");
}
static inline void fm1_usb_rx_sync(void) { __asm__ volatile("ssync" ::: "memory"); }
static inline void fm1_usb_ep_enable(uint32_t eps) { (*(volatile uint32_t *)0x11800u) &= ~(eps << 19); }
static inline uint32_t fm1_usb_sof_take(void)
{
    if (!((*(volatile uint32_t *)0x11800u) & (1u << 13)))
        return 0;
    (*(volatile uint32_t *)0x11800u) |= 1u << 12;
    return 1;
}
