    memset(s, 0, sizeof *s);
    for (uint32_t i = 0; i < P_COUNT; i++) s->p[i] = (uint8_t)(motion_base_value(t, i) + 64);
    s->engine = t->eng_req; s->preset = t->preset;
    s->user[0] = (uint8_t)t->user; s->user[1] = (uint8_t)(t->user >> 8); s->user_native = t->user_native;
    str_cpy(s->name, name ? name : "", sizeof s->name);
    if (s->engine == 12u) { memcpy(s->patch.fm, fm6_patch_of(k), FP_SIZE); s->fm_on = PKV(63)[k]; }
    else if (s->engine == 15u) s->patch.cz = *cz_patch_of(k);
    else if (s->engine == 19u) s->patch.p5 = *p5_patch_of(t);
    else if (s->engine == 10u) s->patch.drum = *drum_patch_of(k);
