    for (uint32_t i = 0; i < P_COUNT; i++) if (!param_kept(i)) t->p[i] = (int16_t)s->p[i] - 64;
    t->eng_req = s->engine; t->preset = s->preset;
    t->user = s->user[0] | (uint16_t)s->user[1] << 8; t->user_native = s->user_native;
    if (s->engine == 12u) { fm6_put_patch(k, s->patch.fm, 1); PKV(63)[k] = s->fm_on; }
    else if (s->engine == 15u) { *cz_patch_of(k) = s->patch.cz; cz_track_accept(t); }
    else if (s->engine == 19u) { *p5_patch_of(t) = s->patch.p5; PKV(35)[k] = 1; }
    else if (s->engine == 10u) *drum_patch_of(k) = s->patch.drum;
