/* Western AUTO2 harmony: the mapped key is the melody, always on top. Chord
 * selection is a pure function of scale/root/transpose and melody pitch class;
 * accompaniment tracks, earlier presses and UI previews cannot change it.
 * Included by chord.c after chord_kit. Fixed searches, no allocation or history. */
typedef struct { uint8_t pitch[3], cost; const char *name; } chord_melody_shape_t;
static const chord_melody_shape_t CH_MELODY_SHAPE[] = {
    {{0,4,7}, 0, ""}, {{0,3,7}, 0, "m"},
    {{0,3,6}, 24, "dim"}, {{0,4,8}, 16, "aug"},
    {{0,5,7}, 18, "sus4"}, {{0,2,7}, 18, "sus2"},
};
static uint32_t chord_melody_rotate(uint32_t bits, int32_t semitones)
{
    uint32_t n = (uint32_t)((semitones % 12 + 12) % 12);
    bits &= 0xFFFu;
    return ((bits << n) | (bits >> (12u - n))) & 0xFFFu;
}
static int32_t chord_melody_mapped(const track_t *t, uint32_t input)
{
    uint32_t allowed = chord_melody_rotate(scale_mask(t), t->p[P_ROOT] + t->p[P_TRANS]);
    int32_t note = (int32_t)input;
    while (note >= 0 && !(allowed & (1u << (uint32_t)(note % 12)))) note--;
    if (note < 0) { note = 0; while (!(allowed & (1u << (uint32_t)(note % 12)))) note++; }
    return note;
}
static int32_t chord_melody_below(int32_t melody, uint32_t pitch_class)
{
    return melody - (melody - (int32_t)pitch_class + 12) % 12;
}
static uint32_t chord_melody_make(const track_t *t, uint32_t input, uint8_t *out, int32_t *rp, uint16_t *maskp)
{
    int32_t tonic = t->p[P_ROOT] + t->p[P_TRANS], melody = chord_melody_mapped(t, input);
    uint32_t allowed = chord_melody_rotate(scale_mask(t), tonic), pc = (uint32_t)melody % 12u;
    *rp = melody; *maskp = 1;
    if (trk_vmode(t) != V_POLY) { out[0] = (uint8_t)melody; return 1; }
    uint32_t root = pc, chosen = 0xFFFFu, mask = 0;
    int32_t best = 0x7FFFFFFF;
    /* Visit roots relative to the tonic so equal scores transpose consistently. */
    for (uint32_t degree = 0; degree < 12u; degree++) {
        uint32_t r = (uint32_t)((tonic + (int32_t)degree + 120) % 12);
        if (!(allowed & (1u << r))) continue;
        /* Tonic harmony anchors its own tones. The fourth/fifth roots are next;
         * a melody-root triad wins ordinary ties. Colour chords are fallbacks,
         * never selected just to chase passing notes in another track. */
        int32_t root_cost = !degree ? 0 : degree == 7u ? 8 : degree == 5u ? 10 : 14;
        for (uint32_t s = 0; s < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0])); s++) {
            uint32_t shape = 0;
            for (uint32_t j = 0; j < 3u; j++) shape |= 1u << CH_MELODY_SHAPE[s].pitch[j];
            uint32_t pcs = chord_melody_rotate(shape, (int32_t)r);
            if ((pcs & ~allowed) || !(pcs & (1u << pc))) continue;
            int32_t score = root_cost + CH_MELODY_SHAPE[s].cost - (r == pc ? 6 : 0);
            if (score < best) { best = score; root = r; chosen = s; mask = shape; }
        }
    }
    int32_t notes[4]; uint32_t n = 0;
    if (chosen < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0]))) {
        for (uint32_t i = 0; i < 3u; i++)
            notes[n++] = chord_melody_below(melody, (root + CH_MELODY_SHAPE[chosen].pitch[i]) % 12u);
    } else {
        /* Keep the melody and two separated lower degrees if no named triad
         * contains it. The display calls this a set rather than inventing a name. */
        notes[n++] = melody;
        int32_t note = melody; uint32_t degree = 0;
        while (n < 3u) {
            note--;
            if (allowed & (1u << (uint32_t)((note + 120) % 12))) {
                degree++;
                if (!(degree & 1u)) notes[n++] = note;
            }
        }
        root = (uint32_t)((notes[2] + 120) % 12);
        for (uint32_t i = 0; i < n; i++) mask |= 1u << (uint32_t)((notes[i] - (int32_t)root + 120) % 12);
    }
    for (uint32_t i = 1; i < n; i++)
        for (uint32_t j = i; j && notes[j] < notes[j-1u]; j--) {
            int32_t x = notes[j]; notes[j] = notes[j-1u]; notes[j-1u] = x;
        }
    /* Every voicing keeps the melody fixed. Only the lower voices move. */
    uint32_t voicing = (uint32_t)t->p[P_VOIC];
    if (voicing == VC_OPEN) notes[0] -= 12;
    else if (voicing == VC_BASS || voicing == VC_INV1 || voicing == VC_INV2) {
        uint32_t bass = root;
        if (voicing != VC_BASS && chosen < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0])))
            bass = (root + CH_MELODY_SHAPE[chosen].pitch[voicing == VC_INV1 ? 1u : 2u]) % 12u;
        uint32_t at = n;
        if (voicing != VC_BASS)
            for (uint32_t i = 0; i + 1u < n; i++)
                if ((uint32_t)((notes[i] + 120) % 12) == bass) { at = i; break; }
        int32_t low = chord_melody_below(melody, bass);
        if (at == n) do { low -= 12; } while (low >= notes[0]);
        else while (low > notes[0]) low -= 12;
        notes[at] = low;
        if (at == n) n++;
    }
    /* At MIDI's lower endpoint omit unavailable accompaniment, never move the
     * melody up an octave to make room for a full chord. */
    uint32_t count = 0;
    for (uint32_t i = 0; i < n; i++) if (notes[i] >= 0) out[count++] = (uint8_t)notes[i];
    for (uint32_t i = 1; i < count; i++)
        for (uint32_t j = i; j && out[j] < out[j-1u]; j--) {
            uint8_t x = out[j]; out[j] = out[j-1u]; out[j-1u] = x;
        }
    *rp = (int32_t)root; *maskp = (uint16_t)mask;
    if (count == 1u) { *rp = melody; *maskp = 1; }
    return count;
}
static void chord_melody_name(char *b, uint32_t root, uint32_t mask)
{
    const char *name = mask == 1u ? "" : " set";
    for (uint32_t i = 0; i < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0])); i++) {
        uint32_t shape = 0;
        for (uint32_t j = 0; j < 3u; j++) shape |= 1u << CH_MELODY_SHAPE[i].pitch[j];
        if (shape == mask) { name = CH_MELODY_SHAPE[i].name; break; }
    }
    str_cpy(b, N_NOTE[root % 12u], 12);
    str_cpy(b + str_len(b), name, 12 - str_len(b));
}
/* the tones of the chord (semitones above *root, ascending, iv[0] = 0) -> their number; DIA may move *root
 * down onto the scale */
static uint32_t chord_tones(const track_t *t, uint32_t mode, int32_t *root, int32_t *iv)
{
    uint32_t n = 0, i;
    if (micro_active(t)) {
        if (mode < CH_MAJ) {
            n = mode == CH_DIA7 ? 4u : 3u;
            for (i = 0; i < n; i++) iv[i] = 2 * (int32_t)i;
        } else {
            for (i = 0; i < 4u && CHORD_SHAPE[mode - CH_MAJ][i] >= 0; i++) {
                int32_t target = micro_pitch(t, *root) + CHORD_SHAPE[mode - CH_MAJ][i] * 10000;
                int32_t lo = 0, hi = 127;
                while (lo < hi) {
                    int32_t mid = (lo + hi) / 2;
                    if (micro_pitch(t, mid) < target) lo = mid + 1; else hi = mid;
                }
                if (lo && target - micro_pitch(t, lo - 1) < micro_pitch(t, lo) - target) lo--;
                iv[n++] = lo - *root;
            }
        }
        return n;
    }
    if (mode >= CH_MAJ) {
        for (i = 0; i < 4u && CHORD_SHAPE[mode - CH_MAJ][i] >= 0; i++)
            iv[n++] = CHORD_SHAPE[mode - CH_MAJ][i];
        return n;
    }
    {
        uint32_t mask = scale_mask(t), deg[12], c = 0, at = 0, guard = 12;
        int32_t r = t->p[P_ROOT];
        if (mask == 0xFFFu)
            mask = SCALE_MASK[1]; /* CHR: no key of its own, the major scale of ROOT */
        while (guard-- && !((mask >> (uint32_t)((*root - r + 120) % 12)) & 1u))
            (*root)--; /* outside the scale: the scale note below */
        for (i = 0; i < 12u; i++)
            if ((mask >> i) & 1u) {
                if (i == (uint32_t)((*root - r + 120) % 12))
                    at = c;
                deg[c++] = i;
            }
        for (i = 0; i < (mode == CH_DIA7 ? 4u : 3u); i++) { /* every other note of the scale */
            uint32_t k = at + 2u * i;
            iv[n++] = (int32_t)deg[k % c] + 12 * (int32_t)(k / c) - (int32_t)deg[at];
        }
        return n;
    }
}
/* the chord on note `root` as track t plays it now -> out (ascending), the number of notes (1..CHORD_MAX);
 * *rp its root, *maskp its tones above the root (bit i: i semitones; 0 = no chord). The root alone when CHRD
 * is OFF, on a kit, or for MONO / LEGATO / UNISON (their chord's root) */
static uint32_t chord_make(const track_t *t, uint32_t root, uint8_t *out, int32_t *rp, uint16_t *maskp)
{
    int32_t iv[4u + 1u], r = (int32_t)root, x;
    uint32_t mode = (uint32_t)t->p[P_CHRD], n, i, j, m = 0;
    int32_t period = (int32_t)scale_note_period(t);
    uint16_t mask = 0;
    *rp = r;
    *maskp = 0;
    int automatic = mode == CH_AUTO || mode == CH_MELODY;
    if (automatic && micro_scale(t)) *maskp = 1;
    if (!mode || mode > CH_MELODY || chord_kit(t) || (automatic && micro_scale(t))) {
        out[0] = (uint8_t)root;
        return 1;
    }
    if (mode == CH_AUTO) return chord_auto_make(t, root, out, rp, maskp);
    if (mode == CH_MELODY) return chord_melody_make(t, root, out, rp, maskp);
    n = chord_tones(t, mode, &r, iv);
    for (i = 0; i < n; i++)
        mask |= (uint16_t)(1u << (micro_active(t) ?
            ((micro_pitch(t, r + iv[i]) - micro_pitch(t, r) + 5000) / 10000 % 12) : iv[i] % 12));
    *rp = r;
    *maskp = mask;
    if (trk_vmode(t) != V_POLY) { /* one voice: the root */
        out[0] = (uint8_t)clamp(r, 0, 127);
        return 1;
    }
    switch (t->p[P_VOIC]) {
    case VC_OPEN: /* 1-5-3(-7): the second tone an octave up */
        if (n >= 3u)
            iv[1] += period;
        break;
    case VC_INV2:
    case VC_INV1:
        for (j = 0; j < (t->p[P_VOIC] == VC_INV2 ? 2u : 1u); j++) { /* the lowest tone an octave up */
            x = iv[0] + period;
            for (i = 1; i < n; i++)
                iv[i - 1u] = iv[i];
            iv[n - 1u] = x;
        }
        break;
    case VC_BASS: /* the root an octave down; a seventh drops its fifth */
        if (n == 4u) {
            iv[2] = iv[3];
            n--;
        }
        for (i = n; i > 0; i--)
            iv[i] = iv[i - 1u];
        iv[0] = -period;
        n++;
        break;
    default:
        break;
    }
    for (i = 1; i < n; i++) /* ascending */
        for (j = i; j > 0 && iv[j - 1u] > iv[j]; j--) {
            x = iv[j];
            iv[j] = iv[j - 1u];
            iv[j - 1u] = x;
        }
    for (i = 0; i < n && m < 4u; i++) { /* inside 0..127, each note once */
        x = r + iv[i];
        if (x < 0 || x > 127 || (m && out[m - 1u] == (uint8_t)x))
            continue;
        if (micro_active(t) && (micro_pitch(t, x) < 0 || micro_pitch(t, x) > 1270000)) continue;
        out[m++] = (uint8_t)x;
    }
    if (!m) {
        out[0] = (uint8_t)clamp(r, 0, 127);
        return 1;
    }
    return m;
}
/* chord_make for a note played now: a chord is kept in chord_last (the CHORD page shows it) */
static uint32_t chord_build(track_t *t, uint32_t root, uint8_t *out)
{
    int32_t r;
    uint16_t mask;
    uint32_t m = chord_make(t, root, out, &r, &mask), i, k = trk_index(t);
    if (t->p[P_CHRD] == CH_AUTO && !micro_scale(t) && !chord_kit(t) && trk_vmode(t) == V_POLY)
        chord_auto_remember(t, r, mask, out, m);
    if (m > 1u || t->p[P_CHRD] == CH_MELODY) {
        PKV(292)[k].root = (uint8_t)clamp(r, 0, 127);
        PKV(292)[k].mask = mask;
        PKV(292)[k].n = (uint8_t)m;
        for (i = 0; i < 4u; i++)
            PKV(292)[k].note[i] = i < m ? out[i] : 0u;
        PKV(292)[k].gen++;
    }
    return m;
}
/* a chord's name from its root and tones (bit i: i semitones above the root): "C", "Cm7", "F#m7b5", "Gsus4",
 * "A5" -> b (12 bytes) */
static void chord_name(char *b, uint32_t root, uint32_t mask)
{
    uint32_t mi = (mask >> 3) & 1u, ma = (mask >> 4) & 1u, b5 = (mask >> 6) & 1u, p5 = (mask >> 7) & 1u;
    uint32_t s5 = (mask >> 8) & 1u, d7 = (mask >> 9) & 1u, m7 = (mask >> 10) & 1u, M7 = (mask >> 11) & 1u;
    const char *q, *x = "";
    str_cpy(b, N_NOTE[root % 12u], 12);
    if (mi && !ma && b5 && !p5)
        q = d7 ? "dim7" : m7 ? "m7b5" : "dim";
    else if (ma && !mi && s5 && !p5)
        q = m7 ? "+7" : M7 ? "+M7" : "aug";
    else if (ma && !mi)
        q = m7 ? "7" : M7 ? "maj7" : d7 ? "6" : "";
    else if (mi)
        q = m7 ? "m7" : M7 ? "mM7" : d7 ? "m6" : "m";
    else if ((mask >> 5) & 1u) { /* no third: suspended */
        q = m7 ? "7" : "";
        x = "sus4";
    } else if ((mask >> 2) & 1u) {
        q = m7 ? "7" : "";
        x = "sus2";
    } else
        q = "5";
    str_cpy(b + str_len(b), q, 12 - str_len(b));
    str_cpy(b + str_len(b), x, 12 - str_len(b));
}
/* the MIDI note (ch, src) of track id - 1 that plays a chord, 0 = none */
static mchord_t *mchord_of(uint32_t ch, uint32_t src, uint32_t id)
{
    uint32_t i;
    for (i = 0; i < 24u; i++)
        if (PKV(291)[i].id == id && PKV(291)[i].ch == ch && PKV(291)[i].src == src)
            return &PKV(291)[i];
    return 0;
}
/* a MIDI-held chord of track id - 1 sounds note */
static int mchord_held(uint32_t id, uint32_t note)
{
    uint32_t i, j;
    for (i = 0; i < 24u; i++)
        if (PKV(291)[i].id == id)
            for (j = 0; j < PKV(291)[i].n; j++)
                if (PKV(291)[i].note[j] == note)
                    return 1;
    return 0;
}
static void mchord_forget(uint32_t track) /* panic: the track's MIDI chords are gone */
{
    chord_auto_forget(track);
    uint32_t i;
    for (i = 0; i < 24u; i++)
        if (PKV(291)[i].id == track + 1u)
            PKV(291)[i].id = 0;
}
/* A division describes the complete first-to-last sweep, not each string gap.
 * Freeze its rate and pitch order at the press; tempo may still change. ARP owns
 * timing while enabled, so it receives the complete chord immediately. */
static uint32_t chord_strum_begin(track_t *t, uint8_t *notes, uint32_t n, chord_strum_t *s, uint32_t vel)
{
    memset(s, 0, sizeof *s);
    uint32_t rate = (uint32_t)t->p[P_STRUM];
    if (!rate || rate >= (sizeof(N_STRUM) / sizeof((N_STRUM)[0])) || n < 2u || t->p[P_AMODE]) return n;
    uint32_t up = t->p[P_STROKE] == 1;
    if (t->p[P_STROKE] == 2) up = PKV(290)[trk_index(t)]++ & 1u;
    if (up) for (uint32_t i = 0; i < n / 2u; i++) {
        uint8_t x = notes[i]; notes[i] = notes[n - 1u - i]; notes[n - 1u - i] = x;
    }
    if (!up && t->p[P_CHRD] == CH_MELODY && !micro_scale(t)) {
        /* The melody sounds on the press; DOWN/UP/ALT order its accompaniment.
         * Freeze that order here so later mode changes cannot delay the tune. */
        uint8_t melody = notes[n - 1u];
        for (uint32_t i = n - 1u; i; i--) notes[i] = notes[i - 1u];
        notes[0] = melody;
    }
    s->total = (uint8_t)n; s->rate = (uint8_t)rate; s->vel = (uint8_t)vel;
    s->beat = seq_beat_samples();
    return 1u;
}
/* Keep elapsed beat fraction through tempo changes and INT/MIDI clock switches. */
static uint32_t chord_strum_due(chord_strum_t *s, uint32_t started, uint32_t elapsed)
{
    static const uint8_t DEN[] = {1, 2, 4, 8, 16, 32, 6, 12};
    uint32_t beat = seq_beat_samples();
    if (s->beat != beat) {
        s->pos = (uint32_t)(((uint64_t)s->pos * beat + s->beat / 2u) / s->beat);
        s->beat = beat;
    }
    s->pos += elapsed;
    uint32_t target = (beat / DEN[s->rate]) * started / (s->total - 1u);
    return s->pos < target ? target - s->pos : 0u;
}
/* ------------------------------------------------------------- arp --- */
static void arp_add(track_t *t, uint32_t note)
{
    uint32_t i;
    if (t->p[P_AHOLD] && t->arp_phys == 0u)
        t->nheld = 0; /* new chord replaces the latched one */
    t->arp_phys++; /* every key-down: arp_remove counts every key-up */
    for (i = 0; i < t->nheld; i++)
        if (t->held[i] == note)
            return; /* repeated note-on: not a new note */
    if (t->nheld < 16u)
        t->held[t->nheld++] = (uint8_t)note;
    if (t->nheld == 1u) {
        t->arp_pos = 0xFFFFFFF; /* fire on this block */
        t->arp_idx = 0xFFFFFFFFu;
    }
}
static void arp_remove(track_t *t, uint32_t note)
{
    uint32_t i, k = 0;
    if (t->arp_phys)
        t->arp_phys--;
    if (t->p[P_AHOLD])
        return;
    for (i = 0; i < t->nheld; i++)
        if (t->held[i] != note)
            t->held[k++] = t->held[i];
    t->nheld = (uint8_t)k;
}
