{
    uint32_t n = PKV(286)[k], i, mc = trk_midi_ch(trk_index(t));
    PKV(288) &= ~(1u << k);
    PKV(287)[k].total = 0;
    PKV(286)[k] = 0;
    for (i = 0; i < n; i++) {
        uint32_t x = PKV(285)[k][i];
        if (midi_local_held(t, x)) continue;
        input_off(t, x);
        if (!midi_track_only(t)) midi_out_event(0x08u | (0x80u | mc) << 8 | x << 16);
    }
}
static void midi_chord_tone(mchord_t *m)
{
    track_t *t = &PKV(11)[m->id - 1u];
    uint32_t note = m->note[m->n];
    uint32_t held = midi_note_held(t, note) || midi_local_held(t, note);
    m->n++;
    /* MPC's duplicate drum pads are separate strikes, even while another pad holds that sound. */
    if (!held || (t->p[P_QUANT] == Q_MPC && drum_track(t))) input_on(t, note, m->strum.vel);
}
/* Return the next string boundary, bounded by this clock advance. Splitting the
 * sequencer here gives the recorder the actual onset, even in batched clocks. */
static uint32_t chord_strum_next(uint32_t limit)
{
    for (uint32_t k = 0; PKV(288) && k < 27u; k++) if (PKV(288) & (1u << k)) {
        uint32_t due = chord_strum_due(&PKV(287)[k], PKV(286)[k], 0);
        if (due < limit) limit = due;
    }
    for (uint32_t k = 0; PKV(289) && k < 24u; k++) if (PKV(289) & (1u << k)) {
        uint32_t due = chord_strum_due(&PKV(291)[k].strum, PKV(291)[k].n, 0);
        if (due < limit) limit = due;
    }
    return limit;
}
static void chord_strum_tick(uint32_t n)
{
    for (uint32_t k = 0; PKV(288) && k < 27u; k++) if (PKV(288) & (1u << k)) {
        chord_strum_t *s = &PKV(287)[k];
        chord_strum_due(s, PKV(286)[k], n);
        while (PKV(286)[k] < s->total && !chord_strum_due(s, PKV(286)[k], 0)) key_chord_tone(k, &PKV(11)[PKV(259)[k]]);
        if (PKV(286)[k] == s->total) PKV(288) &= ~(1u << k);
    }
    for (uint32_t k = 0; PKV(289) && k < 24u; k++) if (PKV(289) & (1u << k)) {
        mchord_t *m = &PKV(291)[k];
        chord_strum_due(&m->strum, m->n, n);
        while (m->n < m->strum.total && !chord_strum_due(&m->strum, m->n, 0)) midi_chord_tone(m);
        if (m->n == m->strum.total) PKV(289) &= ~(1u << k);
    }
}
static void keyboard_block(void)
{
    uint32_t cur = PKV(6).notes, ch, k;
    ch = cur ^ PKV(257); /* keys also sound while entering steps */
    if (!ch) return;
    for (k = 0; k < 27u; k++) {
        if (!((ch >> k) & 1u))
            continue;
        if ((cur >> k) & 1u) { /* the selected track; the key-up goes to the same one */
            PKV(259)[k] = PKV(14).sel;
            if (PKV(256)) { PKV(258)[k]=255u; continue; }
            if ((PKV(6).buttons & PKV(186)) || PKV(188)) {
                PKV(258)[k] = 255u;
                PKV(176) |= 1u << k;
                PKV(187) |= 1u << k;
                PKV(195).req = (int8_t)punch_fx_of_key(k);
                PKV(195).keybit = 1u << k;
                continue;
            }
            if ((PKV(6).buttons & PKV(175)) || PKV(177)) { /* a layer's button held: the key is the layer's (ui_layer.c), */
                PKV(258)[k] = 255u; /* a quick-layer key */
                PKV(176) |= 1u << k;
                continue;
            }
            if (PKV(14).grid == 2u) /* NAME / pattern selection: keys belong to the UI */
                PKV(258)[k] = 255u;
            else if (PKV(14).grid) /* the DRUM grid: a lane key plays its lane, the rest are the UI's */
                PKV(258)[k] = key_black(k) && key_place(k) < 8 ? DRUM_LANE_NOTE[key_place(k)] : 255u;
            else
                PKV(258)[k] = (uint8_t)kb_map(&PKV(11)[PKV(259)[k]], k);
            if (PKV(258)[k] == 255u)
                continue;
            key_on(k, &PKV(11)[PKV(259)[k]]);
        } else {
            if (PKV(187) & (1u << k)) {
                PKV(187) &= ~(1u << k);
                if (PKV(195).keybit == (1u << k)) { PKV(195).req = -1; PKV(195).keybit = 0; }
            }
            if ((PKV(176) >> k) & 1u) {
                PKV(176) &= ~(1u << k);
                continue;
            }
            if (PKV(258)[k] == 255u)
                continue;
            key_off(k, &PKV(11)[PKV(259)[k] % (4 + 4)]);
        }
    }
    PKV(257) = cur;
}
