/* -------------------------------------------------------- sequencer --- */
static void seq_start(void)
{
    PKV(358) = 0; /* MIDI Start also cancels a pending local count-in. */
    PKV(300) = 1;
    PKV(200) = 0; /* every start from the same place: a take repeats exactly */
    uint32_t i;
    PKV(297) = 0;
    PKV(299)++;
    memset(PKV(303), 0, sizeof PKV(303));
    if (!PKV(255).armed && !PKV(14).playing) pattern_sound_begin();
    motion_begin();
    chain_start();
    PKV(255).seek_chase = 0;
    memset(PKV(255).seek_phase, 0, sizeof PKV(255).seek_phase);
    PKV(14).rec_wait = 0;
    PKV(14).rec_pass = PKV(14).rec;
    for (i = 0; i < (4 + 4); i++) { /* every track from its step 0, together */
        track_t *t = &PKV(11)[i];
        if (t->p[P_LTRIG] && t->p[P_LSYNC]) t->lfo_ph = (uint32_t)t->p[P_LPHASE] << 25;
        t->seq_idx = (uint16_t)(t->p[P_SLEN] - 1);
        t->seq_pos = 0x7FFFFFFF; /* step 0 fires on the first block */
        if (!PKV(255).running) PKV(255).seek_samples[i] = PKV(302); /* (a song's are its own: chain_prepare_from) */
        if (PKV(255).seek_samples[i]) {
            uint32_t period = seq_div_samples((uint32_t)t->p[P_SDIV]), loop = recording_loop(t, period);
            uint32_t phase = 0, idx = 0;
            if (loop) chain_div_samples(PKV(255).seek_samples[i], loop, &phase);
            if (PKV(255).seek_samples[i] >= loop) PKV(255).seek_chase |= (uint8_t)(1u << i);
            while (idx + 1u < (uint32_t)t->p[P_SLEN] && phase >= step_samples(t, period, idx)) {
                phase -= step_samples(t, period, idx); idx++;
            }
            t->seq_idx = (uint16_t)((idx + t->p[P_SLEN] - 1u) % t->p[P_SLEN]);
            PKV(255).seek_phase[i] = phase;
        }
        t->rskip_n = 0;
        t->rh_n = 0;
        PKV(354)[i] = 0xFFFFu; /* (capture: step 0 is the first) */
    }
    PKV(302) = 0;
    PKV(352) = PKV(351); /* capture and the jam log: this run */
    PKV(353) = PKV(14).sel;
    PKV(355).n = 0;
    PKV(14).tick = 0;
    PKV(313) = 0; PKV(314) = 0; /* the ARP LED's beat from the top too */
    PKV(14).playing = 1;
    if (click_wanted()) PKV(356)=2;
}
static void seq_release(track_t *t)
{
    uint32_t i;
    for (i = 0; i < t->seq_n; i++)
        if (!(PKV(261)[trk_index(t)][t->seq_notes[i] >> 5] & (1u << (t->seq_notes[i] & 31u))) &&
            t->arp_note != t->seq_notes[i] && !recording_owns(t, t->seq_notes[i]))
            trk_note_off(t, t->seq_notes[i]);
    t->seq_n = 0;
    t->seq_hold = 0;
    t->slide_glide = 0; /* live MONO / LEG keys must not glide after it */
}
