/* EDIT held during live sequence recording erases the selected bank at audio
 * step boundaries. The UI publishes a scoped request; physical release, track
 * changes, disarm and transport stop disable it without waiting for a UI frame. */
static int seq_erase_active(const track_t *t)
{
    uint32_t request = PKV(297), buttons = PKV(6).buttons;
    return (request >> 31) && rec_on(t) && PKV(14).seq_mode && PKV(14).sel == trk_index(t) &&
           (request & 0xFFFFu) == recording_owner(t) && PKV(298) == t->pattern_gen &&
           (buttons & PKV(304)) && !(buttons & ~((request >> 16) & 0x3FFFu));
}
static void seq_erase_clear(step_t *st)
{
    memset(st, 0, sizeof *st);
    st->time = ST_REST;
}
/* Rebuild all affected rounded overview cells in one pass. A late hit can
 * share its rounded cell with an unvisited interval, including across zero. */
static void seq_erase_rebuild(track_t *t, uint64_t touched)
{
    if (!touched) return;
    uint64_t found = 0;
    for (uint32_t s = 0; s < 64; s++) if ((touched >> s) & 1u) {
        step_t *st = &t->step[s];
        st->n = st->hit = st->acc = st->vel = 0;
        st->flags &= (uint8_t)~1u;
    }
    for (uint32_t i = PKV(322)[recording_owner(t)]; i < 1024u; i = PKV(323)[i]) {
        if (!recording_active(t, i)) continue;
        const recorded_note_t *r = &PKV(318)[i];
        uint32_t view = recording_view(t, r);
        if (!((touched >> view) & 1u)) continue;
        found |= (uint64_t)1u << view;
        step_t *st = &t->step[view];
        if (r->vel > st->vel) st->vel = r->vel;
        uint32_t lane = drum_lane(recorded_note(r));
        if (drum_track(t) && recorded_note(r) == DRUM_LANE_NOTE[lane]) {
            st->hit |= (uint8_t)(1u << lane);
            if (r->vel > 110u) st->acc |= (uint8_t)(1u << lane);
        } else {
            uint32_t j;
            for (j = 0; j < st->n && st->note[j] != recorded_note(r); j++);
            if (j == st->n && st->n < 4u) st->note[st->n++] = recorded_note(r);
        }
        if (st->vel > 110u) st->flags |= 1u;
    }
    uint32_t len = (uint32_t)clamp(t->p[P_SLEN], 1, 64);
    for (uint32_t s = 0; s < 64; s++) if (((touched & ~found) >> s) & 1u) {
        seq_erase_clear(&t->step[s]);
        for (uint32_t n = 1; s < len && n < len; n++) {
            step_t *tail = &t->step[(s + n) % len];
            if (tail->time != ST_TIE) break;
            seq_erase_clear(tail);
        }
    }
}
static void seq_erase_pass(track_t *t, uint32_t step, int entered)
{
    uint32_t tr = trk_index(t);
    if (!seq_erase_active(t)) { PKV(303)[tr] = 0; return; }
    if (t->seq_pos >= 0x7FFFFFFFu || (PKV(303)[tr] && !entered)) return;
    int starting = !PKV(303)[tr];
    PKV(303)[tr] = 1;
    uint64_t touched = 0;
    /* (a note played on the grid for the next step, stored in this swung interval, waits for its own step) */
    for (uint32_t i = PKV(322)[recording_owner(t)]; i < 1024u;) {
        uint32_t next = PKV(323)[i];
        if (recording_active(t, i) && (recording_grid_step(t, &PKV(318)[i]) == step ||
            (starting && (recording_sounding(i) || (PKV(320)[i] & 1u))))) {
            recording_undo_capture(t);
            touched |= (uint64_t)1u << recording_view(t, &PKV(318)[i]);
            recording_remove(t, i);
        }
        i = next;
    }
    seq_erase_rebuild(t, touched);
    /* A manual tied chord is one note: remove its onset and its whole tail. */
    uint32_t len = (uint32_t)clamp(t->p[P_SLEN], 1, 64), source = step;
    for (uint32_t n = 0; n < len && t->step[source].time == ST_TIE; n++) source = (source + len - 1u) % len;
    if (!(t->step[source].flags & 4u)) {
        if (t->step[source].time == ST_NOTE && (t->step[source].n || t->step[source].hit)) step = source;
        step_t empty;memset(&empty,0,sizeof empty);empty.time=ST_REST;
        if(memcmp(&empty,&t->step[step],sizeof empty))recording_undo_capture(t);
        seq_erase_clear(&t->step[step]);
        for (uint32_t n = 1; n < len && t->step[(step + n) % len].time == ST_TIE; n++)
            seq_erase_clear(&t->step[(step + n) % len]);
    }
    seq_release(t);
    /* A key already held must not recreate erased ties on its eventual release. */
    t->rh_n = t->rh_ties = t->rskip_n = 0;
    t->rh_elapsed = 0;
}
/* Map a quantized onset back to the compact tempo-relative event format. The
 * inverse swung pair calculation is constant-time, even at a 64-step boundary. */
static void recording_quant_position(const recorded_note_t *r, uint32_t at, uint32_t a, uint32_t b, uint32_t len, recorded_note_t *out)
{
    uint32_t actual = at / (a + b) * 2u, pos = at % (a + b), span = a;
    if (pos >= a) { actual++; pos -= a; span = b; }
    uint32_t fraction = span <= 65536u ? (pos * 65536u + span / 2u) / span :
        (uint32_t)(((uint64_t)pos * 65536u + span / 2u) / span);
    *out = *r;
    out->on = (uint16_t)(fraction > 65535u ? 65535u : fraction);
    uint32_t rounded = out->on >= 65536u / 2u;
    recorded_set_step(out, actual, rounded, rounded && actual + 1u == len);
}
/* Only this take is committed. Preflight every destination before changing any
 * stored timing; an unrelated manual note or its tie tail is never overwritten.
 * Rebuild the overview in one bounded pass, preserving independent gates and
 * all other banks without allocating memory in the audio interrupt. */
static void recording_quantize(track_t *t)
{
    if (!t->p[P_RECQ]) return;
    uint32_t owner = recording_owner(t), q = (uint32_t)t->p[P_RECQ], period = seq_div_samples((uint32_t)t->p[P_SDIV]);
    uint32_t len = (uint32_t)clamp(t->p[P_SLEN], 1, 64), blocked = 0;
    uint32_t a = step_samples(t, period, 0), b = step_samples(t, period, 1);
    recording_sync(t, period);
    /* Playback always caches captured onsets. Only punch-out prepares the
     * quantized targets; no alternate grid enters the playback cursor. */
    for (uint32_t i = PKV(322)[owner]; i < 1024u; i = PKV(323)[i])
        if (PKV(320)[i] & 8u) PKV(324)[i] = recording_quant_on(t, &PKV(318)[i], period, q);
    if (q) for (uint32_t i = PKV(322)[owner]; i < 1024u; i = PKV(323)[i]) {
        if (!(PKV(320)[i] & 8u) || !recording_active(t, i)) continue;
        uint32_t at = PKV(324)[i], actual = at / (a + b) * 2u, pos = at % (a + b), span = a;
        if (pos >= a) { actual++; pos -= a; span = b; }
        uint32_t rounded = (uint64_t)pos * 65536u + span / 2u >= (uint64_t)span * (65536u / 2u);
        uint32_t view = rounded && actual + 1u == len ? 0u : actual + rounded, start = view;
        for (uint32_t n = 0; n < len && t->step[start].time == ST_TIE; n++) start = (start + len - 1u) % len;
        if ((t->step[view].time == ST_TIE || t->step[start].time == ST_NOTE) && !(t->step[start].flags & 4u)) {
            blocked = 1; break;
        }
    }
    uint64_t touched = 0;
    for (uint32_t i = PKV(322)[owner]; i < 1024u; i = PKV(323)[i]) {
        if (!(PKV(320)[i] & 8u)) continue;
        PKV(320)[i] &= (uint8_t)~8u;
        uint32_t at = PKV(324)[i];
        /* Restore the ordinary stored-timing cache even if a preflight blocked
         * the pass. Once committed, QNT cannot alter this take's playback. */
        PKV(324)[i] = recording_raw_on(t, &PKV(318)[i], period);
        if (!q || blocked || !recording_active(t, i)) continue;
        recorded_note_t target; recording_quant_position(&PKV(318)[i], at, a, b, len, &target);
        if (target.on == PKV(318)[i].on && target.step == PKV(318)[i].step) continue;
        uint32_t source = recording_view(t, &PKV(318)[i]), view = recording_view(t, &target);
        if (!(t->step[view].flags & 4u)) {
            t->step[view].probability = t->step[source].probability;
            t->step[view].flags = (t->step[source].flags & 2u) | 4u;
            t->step[view].time = ST_NOTE;
        }
        touched |= (uint64_t)1u << source | (uint64_t)1u << view;
        recording_pitch_remove(i);
        PKV(318)[i] = target;
        recording_pitch_add(i);
        PKV(324)[i] = recording_raw_on(t, &PKV(318)[i], period);
    }
    if (touched) {
        seq_erase_rebuild(t, touched);
        PKV(342)++;
        PKV(326)[trk_index(t)].period = 0;
        PKV(326)[trk_index(t)].ordered_period = 0;
    }
    if (blocked) PKV(343) |= (uint8_t)(1u << trk_index(t));
}
static void seq_stop(void)
{
    for (uint32_t k = 0; k < (4 + 4); k++) chord_auto_forget(k);
    PKV(195).req=-1; PKV(195).keybit=0;
    for (uint32_t t = 0; t < (4 + 4); t++) midi_insert_cancel(t);
    PKV(288) = PKV(289) = 0; /* STOP cancels the unplayed part of live sweeps. */
    PKV(358)=0; PKV(356)=0; PKV(357).env=0; PKV(364)=0; if(PKV(369))audition_stop();
    uint32_t i;
    PKV(297) = 0;
    PKV(299)++;
    uint8_t takes = PKV(14).playing ? PKV(14).rec & ~PKV(14).rec_wait : 0;
    PKV(14).playing = 0;
    PKV(14).rec_wait = PKV(14).rec_pass = 0;
    if (PKV(183)) /* external clock: the arp stops with the transport, */
        for (i = 0; i < (4 + 4); i++) /* its sounding note too (HOLD keeps the latched chord) */
            if (PKV(11)[i].arp_note)
                arp_off(&PKV(11)[i]);
    for (i = 0; i < (4 + 4); i++) {
        recording_stop(&PKV(11)[i]);
        if (PKV(11)[i].rh_n)
            rec_finish(&PKV(11)[i]);
        if ((takes >> i) & 1u) recording_quantize(&PKV(11)[i]);
        recording_undo_finish(&PKV(11)[i]);
        seq_release(&PKV(11)[i]);
        if (midi_track_only(&PKV(11)[i])) midi_track_all_off(&PKV(11)[i]);
        PKV(11)[i].rh_n = 0; /* a recorded note held over the stop: as far as it got */
    }
    chain_stop();
    for (i = 0; i < (4 + 4); i++) if (PKV(11)[i].pattern_next < 16u) pattern_switch(&PKV(11)[i], PKV(11)[i].pattern_next);
    motion_end();
}
/* play one step: TIE extends, REST releases, NOTE (re)triggers its notes, then its lane hits (their GM
 * notes, DRUM_LANE_NOTE; an accented hit at 127); a SLIDE on the previous step makes this one legato with a
 * glide (acid style). skip: bit k = note k, bit 8 + l = the hit of lane l already sounds from live
 * recording (not triggered, not released here). */
static void seq_step(track_t *t, const step_t *s, uint32_t period, uint32_t skip)
{
    skip = recording_step_skip(t, s, skip);
    uint32_t i, j, gate = step_gate(s) ? period * step_gate(s) / 255u : period * (uint32_t)t->p[P_SGATE] / 128u;
    uint32_t vel = (s->flags & 1u) ? 127u : (s->vel ? s->vel : 96u);
    uint32_t slide_in = t->seq_hold && t->seq_n;
    uint32_t len = t->p[P_SLEN] ? (uint32_t)t->p[P_SLEN] : 1u;
    uint32_t next_tie = seq_steps(t)[(t->seq_idx + 1u) % len].time == ST_TIE;
    uint8_t nn[4 + 8], vv[4 + 8]; /* the notes it plays: its notes, then its hits */
    uint32_t m = 0, sk = 0;
    if (step_chance(s) < 100u && rng() % 100u >= step_chance(s)) {
        seq_release(t);
        return;
    }
    if (s->time == ST_TIE) {
        if (t->seq_n) {
            t->seq_off = step_gate(s) ? gate : gate + period / 2u;
            t->seq_hold = (s->flags & 2u) != 0 || next_tie; /* chains hold at any GATE / swing */
        }
        return;
    }
    if (s->time == ST_REST || (!s->n && !s->hit)) {
        seq_release(t);
        return;
    }
    for (i = 0; i < s->n && i < 4u; i++, m++) {
        nn[m] = s->note[i];
        vv[m] = (uint8_t)vel;
        sk |= ((skip >> i) & 1u) << m;
    }
    for (i = 0; i < 8; i++)
        if ((s->hit >> i) & 1u) {
            nn[m] = DRUM_LANE_NOTE[i];
            vv[m] = (uint8_t)((s->acc >> i) & 1u ? 127u : vel);
            sk |= ((skip >> (8u + i)) & 1u) << m;
            m++;
        }
    t->slide_glide = (uint8_t)slide_in;
    if (!slide_in)
        seq_release(t);
    for (i = 0; i < m; i++)
        if (!((sk >> i) & 1u)) {
            trk_note_on(t, nn[i], vv[i]);
            chord_auto_observe(t, nn[i]);
        }
    if (slide_in) /* release what is not held over */
        for (i = 0; i < t->seq_n; i++) {
            for (j = 0; j < m && nn[j] != t->seq_notes[i]; j++)
                ;
            if (j == m)
                trk_note_off(t, t->seq_notes[i]);
        }
    t->seq_n = 0;
    for (i = 0; i < m; i++)
        if (!((sk >> i) & 1u))
            t->seq_notes[t->seq_n++] = nn[i];
    t->seq_off = gate;
    t->seq_hold = (s->flags & 2u) != 0 || next_tie; /* next step a TIE: keep the notes to it */
}
static void seq_grid_tick(track_t *t, uint32_t n)
{
    uint32_t period, len;
    if (t->seq_n && !t->seq_hold) {
        if (t->seq_off <= n)
            seq_release(t);
        else
            t->seq_off -= n;
    }
    if (!PKV(14).playing)
        return;
    if (t->rh_n)
        t->rh_elapsed += n;
    period = seq_div_samples((uint32_t)t->p[P_SDIV]);
    len = (uint32_t)t->p[P_SLEN];
    t->seq_pos += n;
    for (;;) {
        uint32_t cur_len = step_samples(t, period, t->seq_idx);
        if (t->seq_pos < cur_len && t->seq_pos != 0x7FFFFFFFu + n)
            break;
        uint32_t starting = t->seq_pos >= 0x7FFFFFFFu;
        uint32_t punch_in = 0;
        t->seq_pos = starting ? (PKV(255).running ? PKV(255).carry : 0u) : t->seq_pos - cur_len;
        if (starting) {
            t->seq_pos += PKV(255).seek_phase[trk_index(t)]; PKV(255).seek_phase[trk_index(t)] = 0;
        }
        t->seq_idx = (uint16_t)((t->seq_idx + 1u) % (len ? len : 1u));
        if (!t->seq_idx && !starting && !PKV(255).running) {
            uint8_t bit = (uint8_t)(1u << trk_index(t));
            if (PKV(14).rec_pass & (uint8_t)~PKV(14).rec_latch & bit) rec_set(t, 0);
            else if (PKV(14).rec & PKV(14).rec_wait & bit) {
                PKV(14).rec_wait &= (uint8_t)~bit;
                PKV(14).rec_pass |= bit;
                punch_in = 1;
            }
        }
        if (!t->seq_idx && !PKV(255).running && t->pattern_next < 16u) {
            pattern_switch(t, t->pattern_next);
            t->seq_idx = 0;
            period = seq_div_samples((uint32_t)t->p[P_SDIV]);
            len = (uint32_t)t->p[P_SLEN];
        }
        if (!t->seq_idx && !starting) { /* a loop end: an edit waiting on the bank now playing keeps it
                                                         * silent until the UI has done it */
            uint32_t k = trk_index(t);
            PKV(315)[k]++;
            if ((PKV(316)[k] >> t->pattern) & 1u)
                PKV(317) |= (uint8_t)(1u << k);
        }
        PKV(354)[trk_index(t)]++;
        if (!t->seq_idx && t == &PKV(11)[0] && !PKV(255).running)
            jam_loop();
        if (starting && PKV(255).seek_samples[trk_index(t)] && !chain_rest(t)) {
            if (PKV(255).seek_chase & (1u << trk_index(t)))
                for (uint32_t j = 0; j < len; j++) motion_step(t, j, &PKV(305));
            for (uint32_t j = 0; j < t->seq_idx; j++) motion_step(t, j, &PKV(305));
        }
        if (!chain_rest(t)) motion_step(t, t->seq_idx, &PKV(305));
        if (punch_in) rec_begin_held(t);
        seq_erase_pass(t, t->seq_idx, 1);
        if (!seq_erase_active(t)) rec_hold(t, t->seq_idx, len ? len : 1u);
        {
            const step_t *s = &seq_steps(t)[t->seq_idx];
            uint32_t skip = 0, i, k;
            if (t->rskip_n && t->rskip_idx == t->seq_idx) {
                for (k = 0; k < t->rskip_n; k++) {
                    for (i = 0; i < s->n; i++)
                        if (s->note[i] == t->rskip[k])
                            skip |= 1u << i;
                    for (i = 0; i < 8; i++)
                        if (((s->hit >> i) & 1u) && DRUM_LANE_NOTE[i] == t->rskip[k])
                            skip |= 1u << (8u + i);
                }
                t->rskip_n = 0;
            }
            if (chain_rest(t) || ((PKV(317) >> trk_index(t)) & 1u))
                s = &SEQ_HUSH_STEP;
            if (starting && PKV(255).seek_samples[trk_index(t)] && s->time == ST_TIE) {
                uint32_t j = t->seq_idx;
                for (uint32_t count = 0; count < len && seq_steps(t)[j].time == ST_TIE; count++) j = (j + len - 1u) % len;
                if (seq_steps(t)[j].time == ST_NOTE) seq_step(t, &seq_steps(t)[j], period, skip);
            }
            seq_step(t, s, step_gate(s) ? step_samples(t, period, t->seq_idx) : period, skip);
            if (starting) PKV(255).seek_samples[trk_index(t)] = 0;
        }
    }
}
/* Split at pattern boundaries so raw playback follows bank changes and fires
 * loop zero once. MIDI batches may cross several boundaries in one call. */
static void seq_tick(track_t *t, uint32_t n)
{
    if (chain_rest(t)) { seq_grid_tick(t, n); return; }
    seq_erase_pass(t, t->seq_idx, 0);
    if (!((PKV(341) | PKV(14).rec) & (1u << trk_index(t)))) { seq_grid_tick(t, n); return; }
    if (!PKV(14).playing) { seq_grid_tick(t, n); return; }
    if (t->seq_pos >= 0x7FFFFFFFu) {
        uint32_t seek = PKV(255).seek_samples[trk_index(t)] != 0; /* (the first step clears it) */
        seq_grid_tick(t, n);
        recording_zero(t, seek);
        return;
    }
    while (n) {
        uint32_t period = seq_div_samples((uint32_t)t->p[P_SDIV]);
        uint32_t span = step_samples(t, period, t->seq_idx);
        uint32_t chunk = t->seq_pos < span ? span - t->seq_pos : 1u;
        if (chunk > n) chunk = n;
        uint32_t before = t->seq_idx;
        if (PKV(341) & (1u << trk_index(t))) recording_tick(t, chunk);
        seq_grid_tick(t, chunk);
        if (!t->seq_idx && (before || t->p[P_SLEN] == 1) && t->seq_pos < chunk) recording_zero(t, 0);
        n -= chunk;
    }
}
/* A range is a strict input filter, including the DRUM override. SEL keeps its stored value 1.
 * Return 0 for channels outside the range or tracks not in use; releases keep their original owner. */
static track_t *midi_track(uint32_t ch)
{
    uint32_t k, route = (uint32_t)PKV(14).g[G_ROUTE];
    uint32_t first = route > 1u ? (route - 1u) * 4u : 0u;
    if (route != 1u && (ch < first || ch - first >= 4u))
        return 0;
    if (PKV(92) && ch + 1u == PKV(92)) {
        for (k = 0; k < trk_n(); k++)
            if (drum_track(&PKV(11)[k]))
                return &PKV(11)[k];
    }
    if (route == 1u)
        return (&PKV(11)[PKV(14).sel]);
    return ch - first < trk_n() ? &PKV(11)[ch - first] : 0;
}
/* QNT is shared. MPC note routing overrides ROUT and DRUM on every input channel; controllers
 * retain their channel routing and held-note targets. Note-offs use the original saved owner. */
static track_t *midi_note_track(uint32_t ch, uint32_t note)
{
    if (PKV(11)[0].p[P_QUANT] == Q_MPC) {
        uint32_t k = mpc_pad(note) / 16u;
        return k < 4u && k < trk_n() ? &PKV(11)[k] : 0;
    }
    return midi_track(ch);
}
